  const footer=()=>'<footer class="footer"><div class="wrap footergrid"><div><div class="brand">Tivione <b>IPTV</b></div><p>'+t.lead+'</p></div><div><strong>'+t.nav[6]+'</strong><a href="'+href('contact')+'">WhatsApp</a><a href="https://t.me/'+window.TIVIONE_CONFIG.contact.telegram+'">Telegram</a></div><div><strong>Legal</strong><a href="'+href('privacy')+'">Privacy</a><a href="'+href('terms')+'">Terms</a></div></div><div class="wrap"><small>© 2026 Tivione IPTV — '+t.rights+'</small></div></footer>';
