  const support=()=>'<section><div class="wrap band"><div><p class="eyebrow">Tivione</p><h2>'+t.contact+'</h2><p>'+t.contactLead+'</p></div><a class="button" href="'+href('contact')+'">'+t.contactSales+'</a></div></section>';
  const resellerWorkflow=()=>'<section><div class="wrap split"><div><p class="eyebrow">Tivione reseller</p><h2>'+t.workflow+'</h2><p>'+t.workflowText+'</p><a class="button" href="https://t.me/'+window.TIVIONE_CONFIG.contact.telegram+'" target="_blank" rel="noopener noreferrer">Telegram ↗</a></div><div class="grid"><article class="card"><h3>'+t.reseller+'</h3><p>'+t.features[0]+'. '+t.workflowText+'</p></article><article class="card"><h3>Xtream Codes / MAG / M3U</h3><p>'+t.appsLead+'</p></article><article class="card"><h3>'+t.features[5]+'</h3><p>'+t.contactLead+'</p></article></div></div></section>';
  const period=n=>locale==='fr'?n+' mois':locale==='es'?n+' meses':locale==='de'?n+' Monate':locale==='nl'?n+' maanden':locale==='cn'?n+'个月':locale==='ar'?n+' شهرًا':n+' months';
  const credits=locale==='fr'?'crédits':locale==='es'?'créditos':locale==='de'?'Credits':locale==='nl'?'credits':locale==='cn'?'积分':locale==='ar'?'رصيد':'Credits';
  const cards=(data,kind)=>'<section><div class="wrap grid five">'+data.map(x=>'<article class="card"><h3>'+x[0]+(kind==='plan'?' '+period(x[0]):' '+credits)+'</h3><div class="price">'+(x[1]?'€'+x[1]:t.contactSales)+'</div>'+featureList()+'<a class="button" href="'+wa((kind==='plan'?'Tivione '+x[0]+' month subscription':'Tivione reseller '+x[0]+' credits'))+'">'+t.cta+'</a></article>').join('')+'</div></section>';
